            boolean sawDt = false;
            boolean sawTicks = false;
            String script = scriptFile.readString("UTF-8");
            String[] lines = script.split("\\R", -1);

            for (int i = 0; i < lines.length; i++) {
                String line = lines[i].trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }

