            for (ActorRecord actorRecord : actors) {
                Actor actor = actorRecord.actor;
                output.append(actorRecord.id)
                        .append('=')
                        .append(String.format(Locale.ROOT, "%.6f,%.6f", actor.getX(), actor.getY()))
