            if (completedTicks >= ticks) {
                Gdx.app.exit();
                return;
            }

            for (ActorRecord actorRecord : actors) {
                actorRecord.actor.act(dt);
            }

            completedTicks++;
            if (completedTicks >= ticks) {
                Gdx.app.exit();
            }
        }

        @Override
