                    case "dt":
                        requireTokenCount(tokens, 2, lineNumber);
                        if (sawDt) {
                            fail(lineNumber, "dt must appear exactly once");
                        }
                        ensureNoActorsDeclared(lineNumber);
                        dt = parseFloat(tokens[1], lineNumber, "dt");
                        if (!(dt > 0.0f)) {
                            fail(lineNumber, "dt must be > 0");
