                        if (ticks < 0) {
                            fail(lineNumber, "ticks must be >= 0");
                        }
                        sawTicks = true;
                        break;
                    case "actor":
                        requireHeaderDirectives(sawDt, sawTicks, lineNumber);
                        requireTokenCount(tokens, 4, lineNumber);
                        parseActor(tokens, lineNumber);
                        break;
