                Gdx.app.exit();
            }
        }

        @Override
        public void render() {
            if (completedTicks >= ticks) {
                Gdx.app.exit();
                return;
            }

            for (ActorRecord actorRecord : actors) {
                actorRecord.actor.act(dt);
            }

            completedTicks++;
            if (completedTicks >= ticks) {
                Gdx.app.exit();
            }
        }

        @Override
        public void dispose() {
            if (outputWritten) {
                return;
            }

            StringBuilder output = new StringBuilder();
            for (ActorRecord actorRecord : actors) {
